    void showInstance() { System.out.print("I"); }

    public static void main(String[] args) {
        Calls.show();
        new Calls().showInstance();
    }
}

class Decision {
    public static void main(String[] args) {
        int n = 0;
        if (n > 0) System.out.print("positive");
        else if (n == 0) System.out.print("zero");
        else System.out.print("negative");
    }
}

class SumLoop {
    public static void main(String[] args) {
        int sum = 0;
        for (int i = 1; i < 4; i++) sum += i;
        System.out.println(sum);
    }
}

class WhileLoop {
    public static void main(String[] args) {
        int n = 3;
        while (n > 0) {
            System.out.print(n);
            n--;
        }
    }
}

class Branching {
    public static void main(String[] args) {
        for (int i = 1; i <= 5; i++) {
            if (i == 2) continue;
            if (i == 4) break;
            System.out.print(i);
        }
    }
}

class DoOnce {
    public static void main(String[] args) {
        int n = 0;
        do { n++; } while (n < 0);
        System.out.println(n);
    }
}

class SwitchBreak {
    public static void main(String[] args) {
        int n = 1;
        switch (n) {
            case 1: System.out.print("A"); break;
            case 2: System.out.print("B");
            default: System.out.print("C");
        }
    }
}

class MethodCall {
