class LoopCount {
    public static void main(String[] args) {
        int count = 0;
        for (int i = 0; i < 5; i += 2) count++;
        System.out.println(count);
    }
}

class ArrowSwitch {
    public static void main(String[] args) {
        int day = 6;
        String kind = switch (day) {
            case 6, 7 -> "weekend";
            default -> "weekday";
        };
        System.out.println(kind);
    }
}

